    A(0, "Mile is to distance as hour is to:", "time", ["clock", "minute", "day", "speed"], 2, "Unit and what it measures",
      "A mile is a unit for measuring distance, and an hour is a unit for measuring time. A minute is another unit of time, not what is measured."),
    A(0, "Flock is to sheep as:", "pack is to wolves", ["nest is to birds", "barn is to cows", "herd is to farmer", "school is to teacher"], 3, "Group name",
      "A flock is a group of sheep, and a pack is a group of wolves. A barn is where cows are kept, not a word for a group of them."),
